def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    pressure_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                threat = float(bid)
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                    threat += 8.0
                if opp.get('budget', 0) < threat:
                    threat = float(opp.get('budget', 0))
                pressure_bids.append(threat)

    if not alive:
        return float(min(budget, 18.0))

    scarcity = max(0.0, (WATER_REQ * (len(alive) + 1)) - supply)
    urgent = hp <= 3 or no_water_days >= 1
    critical = hp <= 2 or no_water_days >= 2

    if pressure_bids:
        top_pressure = max(pressure_bids)
    elif prev_bids:
        top_pressure = max(prev_bids)
    else:
        top_pressure = 0.0

    if critical:
        bid = max(58.0, top_pressure + 3.0)
    elif urgent:
        bid = max(46.0, top_pressure + 2.0)
    else:
        if top_pressure >= 180.0:
            bid = 14.0 if hp >= 6 else 42.0
        elif top_pressure >= 100.0:
            bid = 20.0 if hp >= 7 else 38.0
        elif top_pressure >= 60.0:
            bid = top_pressure + 1.5
        elif top_pressure > 0.0:
            bid = max(24.0, top_pressure + 1.0)
        else:
            bid = 26.0

    if scarcity > WATER_REQ:
        bid += 8.0
    elif scarcity > 0:
        bid += 4.0

    if supply >= 22:
        bid -= 4.0
    elif supply <= 17:
        bid += 4.0

    if day >= 8 and hp >= 6 and no_water_days == 0:
        bid -= 3.0

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 1.2
    elif day <= 9:
        reserve = DAILY_SALARY * 0.5

    max_affordable = budget - reserve
    if urgent:
        max_affordable = budget
    if max_affordable < 0:
        max_affordable = budget * 0.5

    bid = min(bid, budget, max_affordable)
    if urgent:
        bid = min(max(bid, 35.0), budget)
    else:
        bid = min(max(bid, 8.0), budget)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    # If no one is alive, bid conservatively
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many full water units exist; indices must be int
    units = int(supply / WATER_REQ) if WATER_REQ > 0 else 0

    # Core strategy:
    # - If someone was bidding very high yesterday, raise bid today to avoid being outbid.
    # - Otherwise, bid enough to compete but not drain budget.
    # - If my hp is low, increase aggressiveness.

    hp = my_status['hp']
    budget = my_status['budget']

    # Pressure level from yesterday
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85

    # Base bid scaled by supply units
    # If supply supports only 1 unit, competition is higher -> bid higher.
    if units <= 1:
        base = DAILY_SALARY * 0.65
    elif units == 2:
        base = DAILY_SALARY * 0.55
    else:
        base = DAILY_SALARY * 0.45

    if high_pressure:
        # Match/beat pressure, but cap by available budget
        if hp <= 2:
            target = DAILY_SALARY * 0.95
        elif hp <= 4:
            target = DAILY_SALARY * 0.8
        else:
            target = DAILY_SALARY * 0.7
    else:
        # Normal competition: adjust by hp
        if hp <= 2:
            target = DAILY_SALARY * 0.85
        elif hp <= 4:
            target = base + (DAILY_SALARY * 0.2)
        else:
            target = base

    # Also ensure we don't overspend when budget is tiny
    # (Cindy-like behavior suggests others may burn budget; we conserve.)
    if budget <= DAILY_SALARY * 0.1:
        target = min(target, budget)

    # Final clamp
    bid = min(budget, target)

    # If supply is extremely low relative to WATER_REQ, bid minimal to preserve budget
    if supply < WATER_REQ:
        bid = min(bid, max(1.0, budget * 0.2))

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no alive opponents, bid minimally to secure water cheaply
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    # Collect yesterday's bids from all alive opponents
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Decision logic based on yesterday's highest pressure and current HP
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If previous bids were very high, indicating fierce competition
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # Not critical, try to save budget
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else: # Critical HP, bid aggressively
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else: # Previous bids were moderate, react slightly above them
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # If no previous bids (e.g., first day of meta-round or opponents are new/no trace)
    if my_status['hp'] <= 2: # Critical HP, bid high
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    else: # Not critical, bid moderately
        return min(my_status['budget'], DAILY_SALARY * 0.55)

